UPDATE public.agent_contact_requests SET investor_note = 'This one looks like a good fit for me. Can you reach out to the listing agent and find out if it''s still available and what they''re asking? I''d also like to know what the current rents are and whether the expenses look normal for a building like this before I get too far into it.', updated_at = now() WHERE investor_note LIKE '%T-12%';